import {validateProject} from '../project/project.js'; const KEY='forge-ide-projects-v1', SETTINGS='forge-ide-settings-v1';
export class ProjectRepository { async list(){return Object.values(this.all()).sort((a,b)=>b.updatedAt-a.updatedAt)} all(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')}catch{throw Error('Unable to read browser storage.')}} async save(project){validateProject(project);const all=this.all();all[project.id]=project;localStorage.setItem(KEY,JSON.stringify(all));return project} async get(id){return this.all()[id]||null} async delete(id){const all=this.all();delete all[id];localStorage.setItem(KEY,JSON.stringify(all))} async settings(){return JSON.parse(localStorage.getItem(SETTINGS)||'{}')} async saveSettings(s){localStorage.setItem(SETTINGS,JSON.stringify(s));return s}}
